    public async Task<IReadOnlyList<GallerySource>> GetSourcesAsync(CancellationToken cancellationToken=default)
    {
        await using SqliteConnection connection=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);
        await using SqliteCommand command=connection.CreateCommand();command.CommandText=SourceSelect+" ORDER BY Name COLLATE NOCASE;";
        await using SqliteDataReader reader=await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);List<GallerySource> result=[];
        while(await reader.ReadAsync(cancellationToken).ConfigureAwait(false))result.Add(ReadSource(reader));return result;
    }

    public async Task<GallerySource?> GetSourceAsync(string id,CancellationToken cancellationToken=default)
    {
        await using SqliteConnection connection=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);
        await using SqliteCommand command=connection.CreateCommand();command.CommandText=SourceSelect+" WHERE Id=$id;";command.Parameters.AddWithValue("$id",id);
        await using SqliteDataReader reader=await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);return await reader.ReadAsync(cancellationToken).ConfigureAwait(false)?ReadSource(reader):null;
    }

    public async Task<IReadOnlyList<GallerySourceOverlap>> FindSourceOverlapsAsync(string normalizedFolderPath,CancellationToken cancellationToken=default)
    {
        string candidate=NormalizeDirectory(normalizedFolderPath);IReadOnlyList<GallerySource> sources=await GetSourcesAsync(cancellationToken).ConfigureAwait(false);List<GallerySourceOverlap> overlaps=[];
        foreach(GallerySource source in sources)
        {
            string existing=NormalizeDirectory(source.NormalizedFolderPath);
            if(string.Equals(candidate,existing,StringComparison.OrdinalIgnoreCase))overlaps.Add(new(source,GallerySourceOverlapKind.Exact));
            else if(IsInside(candidate,existing))overlaps.Add(new(source,GallerySourceOverlapKind.ExistingParent));
            else if(IsInside(existing,candidate))overlaps.Add(new(source,GallerySourceOverlapKind.ExistingChild));
        }
        return overlaps;
    }

