VALUES($id,$name,$path,$normalized,$kind,$sub,$enabled,$watch,$hidden,$images,$videos,$privacy,$created,$updated,$last,$home,$filenames,$slideshow,$background,$folderAlbums,$available,$preferred);
""";BindSource(command,source);await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
    }

