    public async Task<GalleryRefreshResult> ApplyScanAsync(GallerySourceScanResult scan,IReadOnlyList<GalleryMediaInspectionResult> inspections,CancellationToken cancellationToken=default)
    {
        if(scan.WasCancelled)return new(scan.Source.Id,0,0,0,0,0,false,scan.Warnings,scan.Duration);
        await using SqliteConnection connection=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);
        if(!scan.RootAvailable)
        {
            await using SqliteCommand unavailable=connection.CreateCommand();unavailable.CommandText="UPDATE GallerySources SET Available=0,UpdatedAtUtc=$at WHERE Id=$id;";unavailable.Parameters.AddWithValue("$id",scan.Source.Id);unavailable.Parameters.AddWithValue("$at",Iso(DateTime.UtcNow));await unavailable.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
            return new(scan.Source.Id,0,0,0,0,scan.Errors.Count,false,scan.Warnings.Concat(scan.Errors).ToArray(),scan.Duration);
        }
        if(!scan.IsComplete||scan.Errors.Count>0)return new(scan.Source.Id,0,0,0,0,scan.Errors.Count,false,scan.Warnings.Concat(scan.Errors).ToArray(),scan.Duration);

        await using SqliteTransaction transaction=(SqliteTransaction)await connection.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);
        try
        {
            Dictionary<string,ExistingMedia> existing=await ReadExistingAsync(connection,transaction,scan.Source.Id,cancellationToken).ConfigureAwait(false);
            HashSet<string> seen=new(StringComparer.OrdinalIgnoreCase);int added=0,updated=0,unchanged=0;DateTime now=DateTime.UtcNow;
            foreach(GalleryMediaInspectionResult inspection in inspections)
            {
                cancellationToken.ThrowIfCancellationRequested();GalleryMediaCandidate value=inspection.Candidate;seen.Add(value.NormalizedFilePath);
                if(existing.TryGetValue(value.NormalizedFilePath,out ExistingMedia? old))
                {
                    bool changed=old.FileSize!=value.FileSize||old.ModifiedAtUtc!=value.ModifiedAtUtc||old.MediaType!=value.MediaType||old.Width!=inspection.Width||old.Height!=inspection.Height||old.DurationMilliseconds!=inspection.DurationMilliseconds||old.Orientation!=inspection.Orientation;
                    await UpdateMediaAsync(connection,transaction,old.Id,inspection,changed,now,cancellationToken).ConfigureAwait(false);
                    if(changed){updated++;await DeleteThumbnailsAsync(connection,transaction,old.Id,cancellationToken).ConfigureAwait(false);}else unchanged++;
                }
                else
                {
                    await InsertMediaAsync(connection,transaction,StableId(scan.Source.Id+"|"+value.NormalizedFilePath),scan.Source.Id,inspection,now,cancellationToken).ConfigureAwait(false);added++;
                }
            }
            string[] missing=existing.Where(pair=>!seen.Contains(pair.Key)&&pair.Value.Available).Select(pair=>pair.Value.Id).ToArray();
            foreach(string id in missing){await using SqliteCommand command=connection.CreateCommand();command.Transaction=transaction;command.CommandText="UPDATE GalleryMediaItems SET Available=0,UpdatedAtUtc=$at WHERE Id=$id;";command.Parameters.AddWithValue("$id",id);command.Parameters.AddWithValue("$at",Iso(now));await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);}
            await using(SqliteCommand source=connection.CreateCommand()){source.Transaction=transaction;source.CommandText="UPDATE GallerySources SET Available=1,LastSuccessfulScanAtUtc=$at,UpdatedAtUtc=$at WHERE Id=$id;";source.Parameters.AddWithValue("$id",scan.Source.Id);source.Parameters.AddWithValue("$at",Iso(now));await source.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);}
            await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);return new(scan.Source.Id,added,updated,unchanged,missing.Length,0,true,scan.Warnings,scan.Duration);
        }
        catch{await transaction.RollbackAsync(CancellationToken.None).ConfigureAwait(false);throw;}
    }

    public async Task<IReadOnlyList<GalleryMediaItem>> QueryAsync(GalleryQuery query,CancellationToken cancellationToken=default)
    {
        await using SqliteConnection connection=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);await using SqliteCommand command=connection.CreateCommand();List<string> where=[];
        if(!query.IncludeHidden)where.Add("m.Hidden=0");if(!query.IncludeUnavailable)where.Add("m.Available=1");if(!query.IncludePrivate)where.Add("s.PrivacyLevel=0");if(query.HomePreviewOnly)where.Add("s.PrivacyLevel=0 AND s.ShowOnHome=1");
        if(query.SourceId is not null){where.Add("m.GallerySourceId=$source");command.Parameters.AddWithValue("$source",query.SourceId);}if(query.MediaType is not null){where.Add("m.MediaType=$mediaType");command.Parameters.AddWithValue("$mediaType",(int)query.MediaType.Value);}if(query.SourceKind is not null){where.Add("s.SourceKind=$sourceKind");command.Parameters.AddWithValue("$sourceKind",(int)query.SourceKind.Value);}if(query.FavoritesOnly)where.Add("m.Favorite=1");if(query.Year is not null){where.Add("CAST(strftime('%Y',COALESCE(m.CapturedAtUtc,m.ModifiedAtUtc)) AS INTEGER)=$year");command.Parameters.AddWithValue("$year",query.Year.Value);}if(query.AlbumId is not null){where.Add("EXISTS(SELECT 1 FROM GalleryAlbumItems ai WHERE ai.GalleryMediaItemId=m.Id AND ai.GalleryAlbumId=$album)");command.Parameters.AddWithValue("$album",query.AlbumId);}if(!string.IsNullOrWhiteSpace(query.SearchText)){where.Add("(m.FileName LIKE $search ESCAPE '\\' OR m.ParentFolder LIKE $search ESCAPE '\\' OR s.Name LIKE $search ESCAPE '\\' OR EXISTS(SELECT 1 FROM GalleryAlbumItems ai JOIN GalleryAlbums a ON a.Id=ai.GalleryAlbumId WHERE ai.GalleryMediaItemId=m.Id AND a.Name LIKE $search ESCAPE '\\'))");command.Parameters.AddWithValue("$search","%"+EscapeLike(query.SearchText.Trim())+"%");}
        string order=query.SortMode switch{GallerySortMode.OldestCaptured=>"COALESCE(m.CapturedAtUtc,m.ModifiedAtUtc) ASC",GallerySortMode.RecentlyAdded=>"m.AddedAtUtc DESC",GallerySortMode.RecentlyOpened=>"m.LastOpenedAtUtc DESC",GallerySortMode.Filename=>"m.FileName COLLATE NOCASE",GallerySortMode.FileSize=>"m.FileSize DESC",_=>"COALESCE(m.CapturedAtUtc,m.ModifiedAtUtc) DESC"};
        command.CommandText=MediaSelect+(where.Count>0?" WHERE "+string.Join(" AND ",where):string.Empty)+$" ORDER BY {order} LIMIT $limit;";command.Parameters.AddWithValue("$limit",Math.Clamp(query.MaximumResults,1,50000));
        await using SqliteDataReader reader=await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);List<GalleryMediaItem> result=[];while(await reader.ReadAsync(cancellationToken).ConfigureAwait(false))result.Add(ReadMedia(reader));return result;
    }

